export function operationsCase({
  db,
  u,
  c,
  action,
  method,
  body,
  tx,
  audit,
  evidence,
  refresh,
  json,
  res,
}) {
  if (action === "operations" && method === "GET") {
    json(res, 200, operationSnapshot(db, c));
    return true;
  }
  if (action === "operations" && method === "POST") {
    let result;
