          return;
        }

        if (action === "extraction-corrections") {
          if (!isInstitution(u) && !isReviewer(u))
            fail(403, "Evidence reviewer permission required");
          const previous = history(id)
              .filter((e) => e.kind === "extraction")
              .at(-1),
